import subprocess
import json
import os
import shutil
import time
from pathlib import Path

import pytest


class TestSidebarIntegration:
    """Integration tests that verify the JS test suite executes correctly."""

    @classmethod
    def setup_class(cls):
        """Ensure npm dependencies are installed."""
        cls.project_root = Path(__file__).parent.parent
        cls.node_modules = cls.project_root / 'node_modules'
        cls.jest_config = cls.project_root / 'jest.config.js'
        cls.package_json = cls.project_root / 'package.json'

        if not cls.node_modules.exists():
            subprocess.run(
                ['npm', 'install'],
                cwd=str(cls.project_root),
                check=True,
                capture_output=True,
                timeout=300
            )

    def _run_jest(self, extra_args=None, timeout=120):
        """Helper to run Jest with consistent error reporting."""
        args = ['npx', 'jest', '--config', 'jest.config.js', '--ci']
        if extra_args:
            args.extend(extra_args)

        result = subprocess.run(
            args,
            cwd=str(self.project_root),
            capture_output=True,
            text=True,
            timeout=timeout
        )
        return result

    def test_js_test_suite_executes(self):
        """Verify the Jest test suite runs without failures."""
        result = self._run_jest()

        assert result.returncode == 0, (
            f"Jest tests failed with exit code {result.returncode}:\n"
            f"STDOUT:\n{result.stdout}\n"
            f"STDERR:\n{result.stderr}"
        )

    def test_coverage_meets_threshold(self):
        """Verify coverage thresholds are met as defined in jest.config.js."""
        result = self._run_jest(
            extra_args=['--coverage', '--json', '--outputFile=coverage-report.json'],
            timeout=180
        )

        assert result.returncode == 0, (
            f"Coverage run failed:\n"
            f"STDOUT:\n{result.stdout}\n"
            f"STDERR:\n{result.stderr}"
        )

        # Parse coverage report
        report_path = self.project_root / 'coverage-report.json'
        assert report_path.exists(), "Coverage report file was not generated"

        try:
            with open(report_path, 'r') as f:
                coverage_data = json.load(f)
        except json.JSONDecodeError as e:
            pytest.fail(f"Coverage report is not valid JSON: {e}")
        finally:
            # Cleanup report file
            report_path.unlink(missing_ok=True)

        # Extract coverage percentages
        coverage_summary = coverage_data.get('coverageMap', {})
        assert coverage_summary, "Coverage map is empty in report"

        total_metrics = {
            'lines': {'covered': 0, 'total': 0},
            'statements': {'covered': 0, 'total': 0},
            'functions': {'covered': 0, 'total': 0},
            'branches': {'covered': 0, 'total': 0}
        }

        for file_path, file_coverage in coverage_summary.items():
            for metric, data in file_coverage.items():
                if metric in total_metrics:
                    total_metrics[metric]['covered'] += data.get('covered', 0)
                    total_metrics[metric]['total'] += data.get('total', 0)

        # Calculate overall percentages
        percentages = {}
        for metric, counts in total_metrics.items():
            if counts['total'] > 0:
                percentages[metric] = (counts['covered'] / counts['total']) * 100
            else:
                percentages[metric] = 100.0  # No code to cover

        # Define thresholds (adjust based on project requirements)
        thresholds = {
            'lines': 80.0,
            'statements': 80.0,
            'functions': 70.0,
            'branches': 70.0
        }

        failures = []
        for metric, threshold in thresholds.items():
            actual = percentages.get(metric, 0)
            if actual < threshold:
                failures.append(
                    f"{metric}: {actual:.2f}% (threshold: {threshold}%)"
                )

        assert not failures, (
            f"Coverage thresholds not met:\n" + "\n".join(failures)
        )

    def test_jest_config_exists(self):
        """Verify the Jest configuration file is present and valid."""
        assert self.jest_config.exists(), (
            f"jest.config.js not found at {self.jest_config}"
        )

        # Basic syntax validation
        result = subprocess.run(
            ['node', '--check', str(self.jest_config)],
            capture_output=True,
            text=True
        )
        assert result.returncode == 0, (
            f"jest.config.js has syntax errors:\n{result.stderr}"
        )

    def test_package_json_has_jest_dependency(self):
        """Verify Jest is declared as a dependency."""
        assert self.package_json.exists(), "package.json not found"

        with open(self.package_json, 'r') as f:
            package_data = json.load(f)

        dependencies = package_data.get('dependencies', {})
        dev_dependencies = package_data.get('devDependencies', {})

        all_deps = {**dependencies, **dev_dependencies}
        assert 'jest' in all_deps, (
            "Jest is not declared in package.json dependencies"
        )

    def test_timeout_handling(self):
        """Verify that Jest execution respects timeout constraints."""
        start_time = time.time()
        timeout_seconds = 5  # Intentionally short to test timeout

        with pytest.raises(subprocess.TimeoutExpired):
            self._run_jest(timeout=timeout_seconds)

        elapsed = time.time() - start_time
        assert elapsed < timeout_seconds + 2, (
            f"Timeout took too long to trigger: {elapsed:.2f}s"
        )

    def test_missing_node_modules_handling(self):
        """Verify graceful handling when node_modules is absent."""
        if not self.node_modules.exists():
            pytest.skip("node_modules already absent, skipping")

        # Temporarily rename node_modules
        backup_path = self.project_root / 'node_modules_backup'
        shutil.move(str(self.node_modules), str(backup_path))

        try:
            result = subprocess.run(
                ['npx', 'jest', '--config', 'jest.config.js', '--ci'],
                cwd=str(self.project_root),
                capture_output=True,
                text=True,
                timeout=30
            )
            # Should fail gracefully, not hang
            assert result.returncode != 0, (
                "Jest should fail when node_modules is missing"
            )
        finally:
            # Restore node_modules
            shutil.move(str(backup_path), str(self.node_modules))

    def test_parallel_execution_safety(self):
        """Verify tests can run in parallel without conflicts."""
        import concurrent.futures

        def run_test_suite():
            result = self._run_jest(timeout=180)
            return result.returncode

        with concurrent.futures.ThreadPoolExecutor(max_workers=2) as executor:
            futures = [executor.submit(run_test_suite) for _ in range(2)]
            results = [f.result() for f in futures]

        assert all(code == 0 for code in results), (
            f"Parallel execution failed: {results}"
        )

    def test_environment_variables_passed(self):
        """Verify environment variables are passed through to Jest."""
        test_env = os.environ.copy()
        test_env['TEST_MODE'] = 'integration'
        test_env['NODE_ENV'] = 'test'

        result = subprocess.run(
            ['npx', 'jest', '--config', 'jest.config.js', '--ci', '--env=jsdom'],
            cwd=str(self.project_root),
            capture_output=True,
            text=True,
            timeout=120,
            env=test_env
        )

        assert result.returncode == 0, (
            f"Jest failed with custom environment:\n{result.stderr}"
        )

    def test_cleanup_artifacts(self):
        """Verify test artifacts are cleaned up after execution."""
        # Run tests with coverage
        self._run_jest(extra_args=['--coverage'], timeout=180)

        # Check for common artifact files
        coverage_dir = self.project_root / 'coverage'
        junit_report = self.project_root / 'junit.xml'

        # Coverage directory should exist (it's a valid artifact)
        assert coverage_dir.exists(), "Coverage directory not generated"

        # Clean up coverage artifacts
        shutil.rmtree(coverage_dir, ignore_errors=True)
        junit_report.unlink(missing_ok=True)

        # Verify cleanup
        assert not coverage_dir.exists(), "Coverage directory not cleaned up"
        assert not junit_report.exists(), "JUnit report not cleaned up"